<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'notifications']); ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">VISÃO GERAL</p><h2>Notificações</h2><p>Eventos importantes gerados pelos módulos do Studio.</p></div></header><div class="studio-notification-list"><?php if($records===[]):?><p class="studio-panel studio-empty">Nenhuma notificação.</p><?php endif;?><?php foreach($records as $record):?><article class="studio-panel <?= $record['read_at']?'':'is-unread' ?>"><div><h3><?= $this->e($record['title']) ?></h3><p><?= $this->e($record['message']) ?></p><small><?= $this->e($record['created_at']) ?></small></div><?php if(!$record['read_at']):?><form method="post"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= $this->e((string)$record['id']) ?>"><button class="studio-button secondary">Marcar como lida</button></form><?php endif;?></article><?php endforeach;?></div></section>
